typedef unsigned int uint32;
typedef unsigned int u_int;

#define NULL 0
#define assert(condition) ((void)0)

struct nglFileBuf
{
	unsigned char* Buf;
	u_int Size;
	u_int UserData;
};

class PanelFile;

class PanelAnim
{
	char* name;
	char padding[0x68];

public:
	PanelAnim* next;
	static PanelAnim* LoadPanelAnim(unsigned char* buffer, int& index, PanelFile* target_panel);
};

class PanelAnimFile
{
	virtual void anchor();

public:
	PanelAnim* obs;
	float totalseconds;
	bool Load(char* filename, PanelFile* target_panel);
	static bool ReadHeader(unsigned char* buffer, int& index);
};

extern void KSReadFile(const char* filename, nglFileBuf* file, u_int align);
extern void KSReleaseFile(nglFileBuf* file);
extern uint32 ReadLong(unsigned char* buffer, int& index);
extern float ReadFloat(unsigned char* buffer, int& index);

bool PanelAnimFile::Load(char* filename, PanelFile* target_panel)
{
	nglFileBuf file;
	file.Buf=NULL; file.Size=0;
	KSReadFile(filename, &file, 1);
//	int buf_size = file.Size;
	unsigned char* buffer = (unsigned char*) file.Buf;
	int index = 0;
	if(!buffer)
	{
		KSReleaseFile(&file);
		assert(0);
		return false;
	}
	if(!ReadHeader(buffer, index))
	{
		KSReleaseFile(&file);
		assert(0);
		return false;
	}
//	uint32 version = 
		ReadLong(buffer, index);
	totalseconds = ReadFloat(buffer, index);
	uint32 nobjects = ReadLong(buffer, index);

	for (u_int i=0; i<nobjects; ++i)
	{
		PanelAnim* anim = PanelAnim::LoadPanelAnim(buffer, index, target_panel);
		if (!anim)
		{
			KSReleaseFile(&file);
			assert(0);
			return false;
		}
		anim->next = obs;
		obs = anim;
	}

	KSReleaseFile(&file);
	return true;
}
